upstream app_servers {
    server 127.0.0.1:8001;
    server 127.0.0.1:8002;
    server 127.0.0.1:8003;
}

server {
    listen 80;
    server_name app.example.com;
    location / {
        proxy_pass http://app_servers;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

upstream api {
    least_conn;
    server 10.0.0.11:8080;
    server 10.0.0.12:8080;
    server 10.0.0.13:8080;
}

server {
    listen 80;
    server_name api.example.com;
    location / {
        proxy_pass http://api;
    }
}

upstream sessions {
    ip_hash;
    server 10.0.0.21:8080;
    server 10.0.0.22:8080;
}

server {
    listen 80;
    server_name cart.example.com;
    location / {
        proxy_pass http://sessions;
    }
}

upstream pool {
    server 10.0.0.31:8080 weight=2;
    server 10.0.0.32:8080 weight=1;
}

server {
    listen 80;
    server_name pool.example.com;
    location / {
        proxy_pass http://pool;
    }
}

upstream dbproxy {
    server 10.0.0.41:5432;
    server 10.0.0.42:5432 backup;
}

server {
    listen 5432;
    proxy_pass http://dbproxy;
}

upstream retry_pool {
    server 10.0.0.51:8080 max_fails=3 fail_timeout=30s;
    server 10.0.0.52:8080 max_fails=3 fail_timeout=30s;
}

server {
    listen 80;
    server_name retry.example.com;
    location / {
        proxy_pass http://retry_pool;
        proxy_next_upstream error timeout http_502 http_503 http_504;
        proxy_next_upstream_tries 3;
    }
}

upstream keepalive_pool {
    server 10.0.0.61:8080;
    server 10.0.0.62:8080;
    keepalive 32;
}

server {
    listen 80;
    server_name keep.example.com;
    location / {
        proxy_pass http://keepalive_pool;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}

upstream ws_pool {
    hash $request_uri consistent;
    server 10.0.0.71:9000;
    server 10.0.0.72:9000;
}

server {
    listen 80;
    server_name ws.example.com;
    location / {
        proxy_pass http://ws_pool;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

upstream maintenance_pool {
    server 10.0.0.81:8080 down;
    server 10.0.0.82:8080 down;
    server 10.0.0.83:8080;
}

server {
    listen 80;
    server_name maint.example.com;
    location / {
        proxy_pass http://maintenance_pool;
    }
}

upstream cookie_pool {
    server 10.0.0.91:8080;
    server 10.0.0.92:8080;
    sticky cookie srv expires=1h;
}

server {
    listen 80;
    server_name cookie.example.com;
    location / {
        proxy_pass http://cookie_pool;
    }
}

resolver 127.0.0.11 valid=10s ipv6=off;

server {
    listen 80;
    server_name dynamic.example.com;
    location / {
        set $backend app:8080;
        proxy_pass http://$backend;
    }
}

upstream ramp {
    server 10.0.1.1:8080 slow_start=30s;
    server 10.0.1.2:8080 slow_start=30s;
}

server {
    listen 80;
    server_name ramp.example.com;
    location / {
        proxy_pass http://ramp;
    }
}

upstream grpc_backend {
    server 10.0.2.1:50051;
    server 10.0.2.2:50051;
}

server {
    listen 443 ssl http2;
    server_name grpc.example.com;
    location / {
        grpc_pass grpc://grpc_backend;
    }
}

upstream critical {
    server 10.0.3.1:8080 max_fails=2 fail_timeout=10s;
    server 10.0.3.2:8080 max_fails=2 fail_timeout=10s;
}

server {
    listen 80;
    server_name critical.example.com;
    location / {
        proxy_pass http://critical;
    }
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /var/www/errors;
        internal;
    }
}

upstream api_pool {
    server 10.0.4.1:8080;
    server 10.0.4.2:8080;
}
upstream media_pool {
    server 10.0.5.1:8090;
    server 10.0.5.2:8090;
}

server {
    listen 80;
    server_name split.example.com;
    location /api/ {
        proxy_pass http://api_pool;
    }
    location /media/ {
        proxy_pass http://media_pool;
    }
}

server {
    listen 80;
    server_name lb.example.com;
    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

upstream cache_affinity {
    hash $request_uri consistent;
    server 10.0.6.1:8080;
    server 10.0.6.2:8080;
    server 10.0.6.3:8080;
}

server {
    listen 80;
    server_name cache.example.com;
    location / {
        proxy_pass http://cache_affinity;
    }
}

upstream monitored {
    server 10.0.7.1:8080 max_fails=5 fail_timeout=15s;
    server 10.0.7.2:8080 max_fails=5 fail_timeout=15s;
    server 10.0.7.3:8080 backup;
}

server {
    listen 80;
    server_name monitored.example.com;
    location / {
        proxy_pass http://monitored;
    }
}

map $http_x_vip $target {
    default      default_pool;
    "yes"        vip_pool;
}
upstream default_pool {
    server 10.0.8.1:8080;
}
upstream vip_pool {
    server 10.0.8.100:8080;
}

server {
    listen 80;
    server_name tiered.example.com;
    location / {
        proxy_pass http://$target;
    }
}

upstream queued {
    server 10.0.9.1:8080 max_conns=200;
    server 10.0.9.2:8080 max_conns=200;
    keepalive 64;
    keepalive_requests 1000;
    keepalive_timeout 60s;
    queue 100;
}

server {
    listen 80;
    server_name queued.example.com;
    location / {
        proxy_pass http://queued;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}
